    "title": "Study",
    "question": "Is there any kind of technology you can use in study?",
    "zh": "学习时有什么技术工具可以用吗？",
    "audio": "https://daxue-oss.koocdn.com/upload/ti/sardine/2437000-2438000/2437641/25cd69c1d3164fa7a2ddc7035507244d.mp3",
